import React, { useRef, useState, useCallback, useId } from 'react';
import './LiquidGlass.css';

// High-fidelity displacement map encoded for optical lens edge refraction
const LENS_DISPLACEMENT_MAP = "data:image/jpeg;base64,";

/**
 * Optical Liquid Glass Component inspired by Apple's liquid glass design
 * Features:
 * - Apple-style sleek specular edge glint (diagonal rim reflection with smooth cursor caustics)
 * - True optical SVG displacement mapping & subtle perimeter chromatic aberration
 * - Zero 3D tilt by default for rock-solid click stability
 * - Light-theme typography preservation
 */
export const LiquidGlass = ({
  children,
  className = '',
  cornerRadius = 9999,
  displacementScale = 24,
  aberrationIntensity = 1.4,
  elasticity = 0.15,
  enableTilt = false,
  reflectionStyle = 'sleek-glint',
  tint = 'crystal',
  onClick,
  style = {}
}) => {
  const containerRef = useRef(null);
  const rawId = useId();
  // Sanitize filter ID for SVG URL compatibility
  const filterId = `lg-${rawId.replace(/[^a-zA-Z0-9_-]/g, '')}`;

  const [mouseOffset, setMouseOffset] = useState({ x: 0, y: 0 });
  const [isHovered, setIsHovered] = useState(false);

  const handleMouseMove = useCallback((e) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const centerX = rect.left + rect.width / 2;
    const centerY = rect.top + rect.height / 2;
    
    // Normalized offset from -1 to 1
    const normX = Math.max(-1, Math.min(1, (e.clientX - centerX) / (rect.width / 2)));
    const normY = Math.max(-1, Math.min(1, (e.clientY - centerY) / (rect.height / 2)));
    
    setMouseOffset({
      x: normX * 100,
      y: normY * 100
    });
  }, []);

  const handleMouseEnter = () => setIsHovered(true);
  const handleMouseLeave = () => {
    setIsHovered(false);
    setMouseOffset({ x: 0, y: 0 });
  };

  // Subtle directional tilt (strictly 0 when enableTilt is false)
  const tiltX = (enableTilt && isHovered) ? -mouseOffset.y * elasticity * 0.1 : 0;
  const tiltY = (enableTilt && isHovered) ? mouseOffset.x * elasticity * 0.1 : 0;
  
  // Sleek horizontal specular glint position along the top edge
  const glintX = isHovered ? 50 + mouseOffset.x * 0.45 : 35;

  // Apple-style sleek specular edge glint background
  const specularBackground = reflectionStyle === 'sleek-glint'
    ? `linear-gradient(135deg, rgba(255, 255, 255, 0.45) 0%, rgba(255, 255, 255, 0.12) 28%, transparent 60%),
       radial-gradient(ellipse 60% 45% at ${glintX}% 0%, rgba(255, 255, 255, 0.65) 0%, rgba(102, 217, 232, 0.15) 35%, transparent 75%)`
    : `radial-gradient(circle at ${glintX}% 30%, rgba(255, 255, 255, 0.55) 0%, rgba(255, 255, 255, 0.15) 35%, transparent 70%)`;

  return (
    <div
      ref={containerRef}
      className={`liquid-glass-wrapper ${className} tint-${tint} ${isHovered ? 'hovered' : ''} ${enableTilt ? 'tilt-enabled' : 'flat-stable'}`}
      onMouseMove={handleMouseMove}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      onClick={onClick}
      style={{
        borderRadius: `${cornerRadius}px`,
        transform: enableTilt ? `perspective(600px) rotateX(${tiltX}deg) rotateY(${tiltY}deg)` : 'none',
        ...style
      }}
    >
      {/* Hidden SVG Optical Chromatic & Displacement Defs */}
      <svg className="lg-filter-defs" aria-hidden="true">
        <defs>
          <filter id={filterId} x="-20%" y="-20%" width="140%" height="140%" colorInterpolationFilters="sRGB">
            <feImage 
              href={LENS_DISPLACEMENT_MAP} 
              result="DISPLACEMENT" 
              preserveAspectRatio="none" 
            />
            {/* Chromatic separation for Red, Green, and Blue */}
            <feDisplacementMap 
              in="SourceGraphic" 
              in2="DISPLACEMENT" 
              scale={displacementScale} 
              xChannelSelector="R" 
              yChannelSelector="G" 
              result="RED_SHIFT" 
            />
            <feDisplacementMap 
              in="SourceGraphic" 
              in2="DISPLACEMENT" 
              scale={displacementScale * (1 - aberrationIntensity * 0.04)} 
              xChannelSelector="R" 
              yChannelSelector="G" 
              result="GREEN_SHIFT" 
            />
            <feDisplacementMap 
              in="SourceGraphic" 
              in2="DISPLACEMENT" 
              scale={displacementScale * (1 - aberrationIntensity * 0.08)} 
              xChannelSelector="R" 
              yChannelSelector="G" 
              result="BLUE_SHIFT" 
            />
            {/* Combine channels with screen blend */}
            <feBlend in="GREEN_SHIFT" in2="BLUE_SHIFT" mode="screen" result="GB_CHANNELS" />
            <feBlend in="RED_SHIFT" in2="GB_CHANNELS" mode="screen" result="FINAL_CHROMATIC" />
            <feComposite in="FINAL_CHROMATIC" in2="SourceGraphic" operator="atop" />
          </filter>
        </defs>
      </svg>

      {/* Optical Refraction Back-layer with frosted blur and liquid filter */}
      <div 
        className="liquid-glass-lens" 
        style={{
          borderRadius: `${cornerRadius}px`,
          filter: `url(#${filterId})`
        }} 
      />

      {/* Apple-style Sleek Specular Edge Glint */}
      <div 
        className="liquid-glass-specular" 
        style={{
          borderRadius: `${cornerRadius}px`,
          background: specularBackground
        }}
      />

      {/* Glass Inner Content (Preserves typography and colors) */}
      <div className="liquid-glass-content">
        {children}
      </div>
    </div>
  );
};

export default LiquidGlass;
